<?php use App\Core\Security; $baseUrl=rtrim((require BASE_PATH.'/config/app.php')['url'],'/');$escape=static fn(mixed $v):string=>Security::escape((string)$v);$assignments=is_array($assignments??null)?$assignments:[];$message=$message??null;?>
<section class="dashboard-page learning-page"><div class="dashboard-topbar"><button class="dashboard-menu-toggle" type="button" data-dashboard-toggle aria-expanded="false" aria-controls="dashboard-sidebar" aria-label="Open dashboard menu"><span></span><span></span><span></span></button><div class="dashboard-breadcrumb"><a href="<?=$escape($baseUrl)?>/dashboard">Workspace</a><i>/</i><a href="<?=$escape($baseUrl)?>/learning?course_id=<?=(int)$course['id']?>"><?=$escape($course['title'])?></a><i>/</i><strong>Assignments</strong></div></div>
  <header class="dashboard-heading"><div><p class="eyebrow">COURSE WORK</p><h1><?=$escape($course['title'])?> assignments</h1><p>Submit your work and follow review feedback here.</p></div></header><?php if($message):?><div class="admin-alert admin-alert-success" role="status"><?=$escape($message)?></div><?php endif;?>
  <?php if($assignments===[]):?><section class="dashboard-panel"><div class="dashboard-empty"><div><h2>No assignments available</h2><p>Published course assignments will appear here.</p></div></div></section><?php else:?><div class="assignment-student-list"><?php foreach($assignments as $a):?><article class="dashboard-panel assignment-student-card"><div class="dashboard-panel-heading"><div><p class="eyebrow"><?=!empty($a['week_number'])?'WEEK '.(int)$a['week_number']:'COURSE ASSIGNMENT'?></p><h2><?=$escape($a['title'])?></h2></div><span class="dashboard-status status-<?=$escape($a['submission_status']??$a['status'])?>"><?=$escape(str_replace('_',' ',ucfirst($a['submission_status']??$a['status'])))?></span></div><p><?=nl2br($escape($a['instructions']??''))?></p><div class="quiz-meta"><span>Maximum <?=$escape($a['max_marks'])?> marks</span><?php if(!empty($a['due_at'])):?><span>Due <?=$escape(date('M j, Y H:i',strtotime($a['due_at'])))?></span><?php endif;?><?php if($a['marks_awarded']!==null):?><span>Score <?=$escape($a['marks_awarded'])?> / <?=$escape($a['max_marks'])?></span><?php endif;?></div><?php if(!empty($a['feedback'])):?><div class="payment-help"><strong>Instructor feedback</strong><p><?=$escape($a['feedback'])?></p></div><?php endif;?>
    <?php if($a['status']==='published' && (empty($a['submission_id'])||($a['submission_status']??'')==='resubmit_requested') && (empty($a['due_at'])||strtotime($a['due_at'].' UTC')>=time())):?><form method="post" action="<?=$escape($baseUrl)?>/learning/assignments/submit" enctype="multipart/form-data" class="admin-form"><input type="hidden" name="_csrf" value="<?=$escape(Security::csrfToken())?>"><input type="hidden" name="assignment_id" value="<?=(int)$a['id']?>"><label class="admin-label">Your response<textarea class="admin-textarea" name="submission_text" rows="5" maxlength="50000" placeholder="Write your response, or attach a file below."></textarea></label><label class="admin-label">Attach file <span>PDF, JPG, PNG, WebP, ZIP or TXT · maximum 10 MB</span><input class="admin-input" type="file" name="submission_file" accept=".pdf,.jpg,.jpeg,.png,.webp,.zip,.txt,application/pdf,image/jpeg,image/png,image/webp,application/zip,text/plain"></label><button class="button" type="submit"><?=($a['submission_status']??'')==='resubmit_requested'?'Submit revised assignment':'Submit assignment'?></button></form><?php elseif(!empty($a['submission_id'])):?><p class="admin-hint">Submitted <?= $escape(date('M j, Y H:i',strtotime($a['submitted_at']))) ?>.</p><?php endif;?></article><?php endforeach;?></div><?php endif;?>
</section>
